pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";
import {Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
        Log original = new Log();
        c.SetLogFile(address(original));
        c.SetMinSum(0);
        c.Initialized();
    }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(c) && actor != address(0));
        amount = bound(amount, 0, 1e30);

        // An attacker tries to swap the log file after initialization.
        Log replacement = new Log();
        vm.prank(actor);
        c.SetLogFile(address(replacement));

        // Deposit from the actor.
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(0);

        // The ORIGINAL log must have recorded the deposit.
        try Log(c. /* original log stays */ address(0)).History(0) {
            assertTrue(false);
        } catch {}

        // Read the original log via the reference captured at setup.
        // (Re-deploy path avoided: use stored address via a fresh lookup.)
        Log original = getOriginalLog();
        try original.History(0) returns (address sender, string memory, uint256 val, uint256) {
            assertTrue(sender == actor && val == amount);
        } catch {
            assertTrue(false);
        }
    }

    Log lastOriginal;
    function storeOriginal(Log l) internal { lastOriginal = l; }
    function getOriginalLog() internal returns (Log) { return lastOriginal; }
}

contract Reverter { fallback() external payable { revert(); } }
