pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log initialLog;

    function setUp() public {
        c = new C();
        initialLog = new Log();
    }

    function testFuzz_property(address newLogAddr) public {
        // configure the log file BEFORE initialization (allowed in both versions)
        c.SetLogFile(address(initialLog));
        c.SetMinSum(1 ether);
        c.Initialized();

        vm.assume(newLogAddr != address(initialLog));

        // after initialization this must be a no-op on the log file
        c.SetLogFile(newLogAddr);

        // rule: once initialized, the configured log file never changes,
        // regardless of the fuzzed address passed to SetLogFile
        assertTrue(address(c.LogFile()) == address(initialLog));
    }
}

contract Log {
    struct Message {
        address Sender;
        string Data;
        uint Val;
        uint Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

